def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'

    last_me, last_opp = history[-1]

    opp_c = 0
    my_c = 0
    for me, op in history:
        if op == 'C':
            opp_c += 1
        if me == 'C':
            my_c += 1

    recent_len = 10
    if n < recent_len:
        recent_len = n
    start = n - recent_len
    recent_opp_c = 0
    for i in range(start, n):
        if history[i][1] == 'C':
            recent_opp_c += 1

    tail_d = 0
    for i in range(n - 1, -1, -1):
        if history[i][1] == 'D':
            tail_d += 1
        else:
            break

    friendly = 0
    if n > 1:
        for i in range(1, n):
            if history[i - 1][0] == 'D' and history[i][1] == 'C':
                friendly += 1

    opp_rate = opp_c / n
    recent_rate = recent_opp_c / recent_len
    my_rate = my_c / n

    if last_opp == 'D':
        if last_me == 'D':
            if opp_c == 0:
                if tail_d % 6 == 0:
                    return 'C'
                return 'D'
            if opp_rate < 0.35 or recent_rate < 0.35 or tail_d >= 5:
                return 'D'
            return 'C'

        if tail_d >= 4:
            return 'D'
        if tail_d >= 3 and recent_rate < 0.45:
            return 'D'
        if opp_rate < 0.2 or recent_rate < 0.2:
            return 'D'
        return 'C'

    if opp_c == n and friendly > 0:
        if n >= 88 or my_rate > 0.76:
            return 'D'
        return 'C'

    if last_me == 'D':
        if n >= 97:
            return 'D'
        return 'C'

    if n >= 20 and opp_c == n and my_c == n:
        return 'D'

    return 'C'
